import React, { useState } from 'react';
import { toast } from 'react-toastify';
import { login, signup } from '../services/api';
import './Login.css';

// Quezon City Urban Agriculture Locations & Sector Coordinates
const QUEZON_CITY_LOCATIONS = [
  { name: 'Quezon City, Diliman', lat: 14.6538, lon: 121.0685, district: 'District 4', desc: 'UP Diliman / Agri Research / QMC' },
  { name: 'Quezon City, Bagong Silangan', lat: 14.7075, lon: 121.1120, district: 'District 2', desc: 'Model Urban Farm / Vegetable Community' },
  { name: 'Quezon City, Payatas', lat: 14.7156, lon: 121.1118, district: 'District 2', desc: 'Payatas Urban Agriculture Site' },
  { name: 'Quezon City, Batasan Hills', lat: 14.6865, lon: 121.0964, district: 'District 2', desc: 'Batasan Agronomy Area' },
  { name: 'Quezon City, Novaliches', lat: 14.7333, lon: 121.0333, district: 'District 5', desc: 'Novaliches Proper Farming Sector' },
  { name: 'Quezon City, Fairview', lat: 14.7042, lon: 121.0603, district: 'District 5', desc: 'North Fairview Agro-District' },
  { name: 'Quezon City, Commonwealth', lat: 14.6883, lon: 121.0825, district: 'District 2', desc: 'Commonwealth Urban Farm Project' },
  { name: 'Quezon City, Tandang Sora', lat: 14.6736, lon: 121.0475, district: 'District 6', desc: 'Tandang Sora Community Gardens' },
  { name: 'Quezon City, Pasong Tamo', lat: 14.6850, lon: 121.0550, district: 'District 6', desc: 'Pasong Tamo Crop Belt' },
  { name: 'Quezon City, Holy Spirit', lat: 14.6820, lon: 121.0770, district: 'District 2', desc: 'Holy Spirit Agri Park' },
  { name: 'Quezon City, Matandang Balara', lat: 14.6650, lon: 121.0820, district: 'District 3', desc: 'Balara Nursery & Research Beds' },
  { name: 'Quezon City, San Bartolome', lat: 14.7050, lon: 121.0350, district: 'District 5', desc: 'San Bartolome Green Zone' },
  { name: 'Quezon City, Greater Lagro', lat: 14.7220, lon: 121.0680, district: 'District 5', desc: 'Greater Lagro Farming Sector' },
  { name: 'Quezon City, Project 6', lat: 14.6600, lon: 121.0380, district: 'District 1', desc: 'Project 6 Agricultural Nursery' }
];

function findNearestQCLocation(lat, lon) {
  let nearest = QUEZON_CITY_LOCATIONS[0];
  let minDistance = Infinity;
  for (const loc of QUEZON_CITY_LOCATIONS) {
    const d = Math.hypot(loc.lat - lat, loc.lon - lon);
    if (d < minDistance) {
      minDistance = d;
      nearest = loc;
    }
  }
  return nearest;
}

function isWithinQuezonCity(lat, lon) {
  return lat >= 14.58 && lat <= 14.78 && lon >= 120.98 && lon <= 121.16;
}

function Login({ onLoginSuccess }) {
  const [isDev, setIsDev] = useState(false);
  const [email, setEmail] = useState('farmer@agri.coop');
  const [password, setPassword] = useState('password123');
  const [rememberMe, setRememberMe] = useState(true);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);

  // Accurate Location state for Farmer side (focused on Quezon City)
  const [isLocating, setIsLocating] = useState(false);
  const [locationMeta, setLocationMeta] = useState(null);

  // Sign up modal state
  const [showSignupModal, setShowSignupModal] = useState(false);
  const [signupForm, setSignupForm] = useState({
    name: '',
    age: 28,
    email: '',
    password: '',
    role: 'farmer',
    farmName: '',
    farmLocation: 'Quezon City, Diliman',
    organization: ''
  });

  const handleDetectLocation = () => {
    if (!navigator.geolocation) {
      toast.error('Geolocation is not supported by your browser.');
      return;
    }

    setIsLocating(true);
    toast.info('📍 Pinpointing accurate GPS coordinates in Quezon City...');

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const { latitude, longitude, accuracy } = pos.coords;
        const latFixed = latitude.toFixed(4);
        const lonFixed = longitude.toFixed(4);
        const inQC = isWithinQuezonCity(latitude, longitude);
        const nearestLoc = findNearestQCLocation(latitude, longitude);

        // Auto-select the matched Quezon City location in the dropdown
        setSignupForm(prev => ({
          ...prev,
          farmLocation: nearestLoc.name
        }));

        setLocationMeta({
          latitude: latFixed,
          longitude: lonFixed,
          accuracy: Math.round(accuracy),
          matchedLocation: nearestLoc.name,
          district: nearestLoc.district,
          inQC: inQC
        });

        if (inQC) {
          toast.success(`🎯 Verified within Quezon City: ${nearestLoc.name} (±${Math.round(accuracy)}m)`);
        } else {
          toast.info(`📍 Device GPS: ${latFixed}°, ${lonFixed}°. Focused to Quezon City: Selected closest sector (${nearestLoc.name}).`);
        }
        setIsLocating(false);
      },
      (err) => {
        console.warn('Geolocation error:', err);
        let msg = 'Could not acquire GPS position.';
        if (err.code === 1) msg = 'Location permission was denied. Please select your Quezon City farm location from the dropdown.';
        else if (err.code === 2) msg = 'GPS signal unavailable. Please select your Quezon City location from the dropdown.';
        else if (err.code === 3) msg = 'Location request timed out. Please select from the dropdown.';
        toast.warn(msg);
        setIsLocating(false);
      },
      { enableHighAccuracy: true, timeout: 12000, maximumAge: 0 }
    );
  };

  const toggleMode = (targetIsDev) => {
    setIsDev(targetIsDev);
    if (targetIsDev) {
      if (email === 'farmer@agri.coop') setEmail('dev@agri.coop');
    } else {
      if (email === 'dev@agri.coop') setEmail('farmer@agri.coop');
    }
  };

  const handleQuickFill = (role) => {
    if (role === 'farmer') {
      setIsDev(false);
      setEmail('farmer@agri.coop');
      setPassword('password123');
      toast.info('Loaded Farmer demo credentials.');
    } else {
      setIsDev(true);
      setEmail('dev@agri.coop');
      setPassword('password123');
      toast.info('Loaded Dev & Research demo credentials.');
    }
  };

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    if (!email || !password) {
      toast.warn('Please enter both email and password.');
      return;
    }

    setLoading(true);
    const role = isDev ? 'dev' : 'farmer';

    try {
      // Call backend API
      const res = await login(email, password, role);
      if (res.success && res.user) {
        toast.success(res.message || `Welcome, ${res.user.name}!`);
        if (onLoginSuccess) {
          onLoginSuccess(res.user);
        }
      } else {
        toast.error(res.error || 'Authentication failed.');
      }
    } catch (err) {
      console.warn('Backend login fallback:', err);
      // Fallback demo authentication if backend is unreachable
      const cleanEmail = email.trim().toLowerCase();
      if (cleanEmail === 'farmer@agri.coop' || !isDev) {
        const fallbackUser = {
          name: cleanEmail === 'farmer@agri.coop' ? 'John Miller' : cleanEmail.split('@')[0],
          email: cleanEmail,
          role: 'farmer',
          profile: { farmName: 'Green Valley Organic Farms' }
        };
        toast.success(`Welcome, ${fallbackUser.name}! (Farmer Mode)`);
        if (onLoginSuccess) onLoginSuccess(fallbackUser);
      } else {
        const fallbackUser = {
          name: cleanEmail === 'dev@agri.coop' ? 'Alex Chen' : cleanEmail.split('@')[0],
          email: cleanEmail,
          role: 'dev',
          profile: { organization: 'AgriTech AI Labs' }
        };
        toast.success(`Welcome, ${fallbackUser.name}! (Dev & Research Mode)`);
        if (onLoginSuccess) onLoginSuccess(fallbackUser);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleSignupSubmit = async (e) => {
    e.preventDefault();
    if (!signupForm.name || !signupForm.email || !signupForm.password) {
      toast.warn('Please fill in all required fields.');
      return;
    }

    setLoading(true);
    try {
      const submissionData = {
        ...signupForm,
        farmLocation: (signupForm.role === 'farmer' && locationMeta)
          ? `${signupForm.farmLocation} (${locationMeta.latitude}° N, ${locationMeta.longitude}° E)`
          : signupForm.farmLocation
      };
      const res = await signup(submissionData);
      if (res.success && res.user) {
        toast.success(`Profile created! Welcome, ${res.user.name}.`);
        setShowSignupModal(false);
        if (onLoginSuccess) {
          onLoginSuccess(res.user);
        }
      } else {
        toast.error(res.error || 'Registration failed.');
      }
    } catch (err) {
      console.error('Signup error:', err);
      const errMsg = err.response?.data?.error || err.message || 'Signup failed';
      toast.error(errMsg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`login-page-container ${isDev ? 'theme-dev' : 'theme-farmer'}`}>
      <div className="login-card">
        {/* Header with Title and Mode Badge */}
        <div className="login-header">
          <div className="header-top">
            <div className="header-brand">
              <div className="header-icon-slot">
                {isDev ? '💻' : '🌾'}
              </div>
              <div>
                <h1>ClimaYield-X</h1>
                <p className="header-subtitle">
                  A Data-Driven SARIMA–LSTM Hybrid Model for Predicting Yield Instability in Short-Cycle Vegetables
                </p>
              </div>
            </div>
            <span className="account-badge">
              {isDev ? 'Dev / Researcher Portal' : 'Farmer Portal'}
            </span>
          </div>
        </div>

        {/* Farmer vs Dev Side Interactive Switch */}
        <div className="switch-wrapper">
          <span 
            className={`switch-label ${!isDev ? 'active-farm' : ''}`}
            onClick={() => toggleMode(false)}
          >
            🌾 FarmerSide
          </span>

          <div 
            className={`toggle-track ${isDev ? 'is-dev' : ''}`}
            onClick={() => toggleMode(!isDev)}
            title="Toggle between Farmer and Dev login modes"
          >
            <div className="toggle-knob">
              {isDev ? '💻' : '🌾'}
            </div>
          </div>

          <span 
            className={`switch-label ${isDev ? 'active-dev' : ''}`}
            onClick={() => toggleMode(true)}
          >
            💻 DevSide
          </span>
        </div>

        {/* Active Panel Form */}
        <div className="panel">
          <div className="panel-title">
            <span>{isDev ? '💻 Dev & Pipeline Access' : '🌾 Field Operations & Weather Access'}</span>
          </div>
          <div className="panel-sub">
            {isDev 
              ? 'Hyperparameter tuning, residual learning analysis, and model retraining controls.'
              : 'Local field forecasting, rainfall alerts, irrigation timing, and crop yield projections.'}
          </div>

          {/* 1-Click Quick Fill Helper */}
          <div className="quick-fill-row">
            <button 
              type="button" 
              className="btn-quick-fill"
              onClick={() => handleQuickFill('farmer')}
            >
              ⚡ Fill Farmer Demo
            </button>
            <button 
              type="button" 
              className="btn-quick-fill"
              onClick={() => handleQuickFill('dev')}
            >
              ⚡ Fill Dev Demo
            </button>
          </div>

          <form onSubmit={handleLoginSubmit}>
            {/* Email Field */}
            <div className="login-input-group">
              <label>{isDev ? 'Engineering ID / Email' : 'Farm ID / Email Address'}</label>
              <div className="login-input-wrapper">
                <span className="login-input-icon">{isDev ? '📧' : '🧑‍🌾'}</span>
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder={isDev ? 'dev@agri.coop' : 'farmer@agri.coop'}
                  required
                />
              </div>
            </div>

            {/* Password Field */}
            <div className="login-input-group">
              <label>Password</label>
              <div className="login-input-wrapper">
                <span className="login-input-icon">🔒</span>
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="••••••••"
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  style={{ background: 'none', border: 'none', cursor: 'pointer', opacity: 0.6, fontSize: '0.9rem' }}
                >
                  {showPassword ? '👁️' : '🙈'}
                </button>
              </div>
            </div>

            {/* Remember Me & Forgot Password */}
            <div className="login-options-row">
              <label className="remember-label">
                <input
                  type="checkbox"
                  checked={rememberMe}
                  onChange={(e) => setRememberMe(e.target.checked)}
                />
                Remember this terminal
              </label>
              <span 
                className="forgot-link"
                onClick={() => toast.info('Default demo password is: password123')}
              >
                Forgot password?
              </span>
            </div>

            {/* Submit Button */}
            <button 
              type="submit" 
              className="btn-auth-submit"
              disabled={loading}
            >
              {loading 
                ? '⏳ Verifying Credentials...' 
                : isDev 
                  ? '💻 Enter Dev & Research Suite' 
                  : '🌾 Enter Field Dashboard'}
            </button>
          </form>

          {/* Signup Trigger */}
          <div className="auth-switch-prompt">
            Don't have an account yet?{' '}
            <button 
              type="button"
              className="auth-switch-btn"
              onClick={() => {
                setSignupForm(prev => ({ ...prev, role: isDev ? 'dev' : 'farmer' }));
                setShowSignupModal(true);
              }}
            >
              Create {isDev ? 'Dev Profile' : 'Farm Profile'}
            </button>
          </div>
        </div>
      </div>

      {/* Signup Modal */}
      {showSignupModal && (
        <div className="auth-modal-overlay" onClick={() => setShowSignupModal(false)}>
          <div className="auth-modal-card" onClick={(e) => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
              <h3 style={{ margin: 0, color: '#2c3e50' }}>
                {signupForm.role === 'dev' ? '💻 Create Dev & Research Account' : '🌾 Register New Farm Profile'}
              </h3>
              <button 
                onClick={() => setShowSignupModal(false)}
                style={{ background: 'none', border: 'none', fontSize: '1.2rem', cursor: 'pointer' }}
              >
                ✖
              </button>
            </div>

            <form onSubmit={handleSignupSubmit}>
              <div className="login-input-group">
                <label>Full Name</label>
                <div className="login-input-wrapper">
                  <input
                    type="text"
                    value={signupForm.name}
                    onChange={(e) => setSignupForm({ ...signupForm, name: e.target.value })}
                    placeholder={signupForm.role === 'dev' ? 'Alex Chen' : 'John Miller'}
                    required
                  />
                </div>
              </div>

              <div className="login-input-group">
                <label>Age</label>
                <div className="login-input-wrapper">
                  <input
                    type="number"
                    min="18"
                    max="99"
                    value={signupForm.age}
                    onChange={(e) => setSignupForm({ ...signupForm, age: e.target.value })}
                    placeholder="e.g. 30"
                    required
                  />
                </div>
              </div>

              <div className="login-input-group">
                <label>Email Address</label>
                <div className="login-input-wrapper">
                  <input
                    type="email"
                    value={signupForm.email}
                    onChange={(e) => setSignupForm({ ...signupForm, email: e.target.value })}
                    placeholder="user@organization.com"
                    required
                  />
                </div>
              </div>

              <div className="login-input-group">
                <label>Password</label>
                <div className="login-input-wrapper">
                  <input
                    type="password"
                    value={signupForm.password}
                    onChange={(e) => setSignupForm({ ...signupForm, password: e.target.value })}
                    placeholder="Create a secure password"
                    required
                  />
                </div>
              </div>

              {signupForm.role === 'farmer' && (
                <>
                  <div className="login-input-group">
                    <label>Farm Name</label>
                    <div className="login-input-wrapper">
                      <span className="login-input-icon">🏡</span>
                      <input
                        type="text"
                        value={signupForm.farmName}
                        onChange={(e) => setSignupForm({ ...signupForm, farmName: e.target.value })}
                        placeholder="e.g. Green Valley Organic Farm"
                      />
                    </div>
                  </div>

                  <div className="login-input-group">
                    <label>Farm Location (Quezon City)</label>
                    <div className="login-input-wrapper">
                      <span className="login-input-icon">📍</span>
                      <select
                        value={signupForm.farmLocation}
                        onChange={(e) => setSignupForm({ ...signupForm, farmLocation: e.target.value })}
                        className="qc-location-dropdown"
                        required
                      >
                        {QUEZON_CITY_LOCATIONS.map((loc) => (
                          <option key={loc.name} value={loc.name}>
                            {loc.name} — {loc.desc} ({loc.district})
                          </option>
                        ))}
                      </select>
                    </div>

                    {/* Accurate Farm Location Feature under Farm Location Field */}
                    <div className="qc-gps-feature-card">
                      <div className="qc-gps-header">
                        <div className="qc-gps-title">
                          <span>🛰️</span>
                          <span>Accurate Farm Location GPS (Quezon City)</span>
                        </div>
                        <button
                          type="button"
                          onClick={handleDetectLocation}
                          disabled={isLocating}
                          className="btn-gps-detect"
                          title="Pinpoint your device's exact GPS coordinates and match to the nearest Quezon City farm sector"
                        >
                          {isLocating ? '⏳ Pinpointing GPS...' : '📍 Pinpoint QC GPS'}
                        </button>
                      </div>

                      {locationMeta ? (
                        <div className={`qc-gps-status-box ${locationMeta.inQC ? 'qc-verified' : 'qc-calibrated'}`}>
                          <div className="qc-status-header">
                            <span className="qc-status-tag">
                              {locationMeta.inQC ? '✅ Quezon City GPS Verified' : '📍 Focused & Calibrated to Quezon City'}
                            </span>
                            <span className="qc-accuracy-tag">
                              Accuracy: ±{locationMeta.accuracy}m
                            </span>
                          </div>
                          <div className="qc-coords-info">
                            <span>Lat {locationMeta.latitude}° · Lon {locationMeta.longitude}°</span>
                            <span>•</span>
                            <span>Auto-Aligned: {locationMeta.matchedLocation}</span>
                          </div>
                        </div>
                      ) : (
                        <p className="qc-gps-hint">
                          Tap <strong>Pinpoint QC GPS</strong> to acquire your exact coordinates and auto-align your location to the nearest agricultural sector in Quezon City.
                        </p>
                      )}
                    </div>
                  </div>
                </>
              )}

              <div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
                <button 
                  type="button" 
                  className="btn-secondary" 
                  style={{ flex: 1 }}
                  onClick={() => setShowSignupModal(false)}
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  className="btn-auth-submit" 
                  style={{ flex: 2 }}
                  disabled={loading}
                >
                  {loading ? 'Creating...' : 'Register & Enter'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default Login;
